#!/usr/bin/env bash
set -euo pipefail
export GIT_CONFIG_NOSYSTEM=1
export GIT_CONFIG_GLOBAL=/dev/null
export GIT_TERMINAL_PROMPT=0
export GIT_EDITOR=true
export GIT_PAGER=cat
export LC_ALL=C
RUN=$(mktemp -d "$TMPDIR/git-macos-evidence.XXXXXX")
STATUS=0
git --version
uname -s
printf '%s' '' | base64 -D > "$RUN/git-github-26-5.sh"
if bash "$RUN/git-github-26-5.sh" > "$RUN/git-github-26-5.log" 2>&1; then :; else STATUS=1; fi
cat "$RUN/git-github-26-5.log"
printf "MACOS_DRIVER_EXIT %s\n" "$STATUS"
exit "$STATUS"
